INSERT INTO `dnd_story_faction` (`id`, `name`, `description`, `sort`) VALUES
('ironforge', 'Ironforge', 'King Magni\'s hold and the Mountaineers who keep its roads.', 0),
('explorers', 'The Explorers\' League', 'Diggers, scholars and map-makers, always somewhere they shouldn\'t be.', 1),
('stormwind', 'Stormwind', 'The human kingdom, its watch and its nobles.', 2),
('darkiron', 'The Dark Irons', 'Ironforge\'s old enemy, back in the mountains in force.', 3),
('syndicate', 'The Underworld', 'Smugglers, thieves and the Syndicate - who owes whom, and who knows.', 4),
('horde', 'The Horde', 'Orgrimmar, Thunder Bluff and the Undercity, and what they make of you.', 5),
('frostmane', 'The Frostmane', 'The trolls of Dun Morogh\'s peaks, their war-chiefs and their seers.', 6);
INSERT INTO `dnd_story_thread` (`id`, `title`, `sort`) VALUES
('copperveins', 'The Coppervein Claim', 0),
('crown', 'The Crown of Ironforge', 1),
('lady', 'The Lady of Stormwind', 2),
('drums', 'The Drums of War', 3),
('doors', 'The Deep Doors', 4),
('twilight', 'The Twilight\'s Hammer', 5),
('exiles', 'The Exiles of Gnomeregan', 6),
('advance', 'The Dark Iron Advance', 7),
('frostmane', 'The Frostmane', 8),
('masons', 'The Stonemasons\' Due', 9),
('dragonmaw', 'The Dragonmaw', 10),
('cloaks', 'The Grey Cloaks', 11);
INSERT INTO `dnd_story_entry` (`thread`, `idx`, `cond`, `text`) VALUES
('copperveins', 0, 'resolved:7', 'In Coldridge Valley an old prospector, Grumbold Coppervein, met us with a pick and a temper, sure we\'d come to jump his claim.'),
('copperveins', 1, 'story:grumbold_knows', 'His seam was fool\'s gold, and the claim was never anyone\'s to sell: he\'d bought it from a smooth-tongued stranger in Kharanos who left in a hurry. Grumbold went after him.'),
('copperveins', 2, 'story:grumbold_kin', 'He took us for kin and waved us through. As far as we know, he\'s still digging.'),
('copperveins', 3, 'story:grumbold_broke', 'His diggers walked out on him, three weeks unpaid. He sat down on his rocks and wanted only a drink.'),
('copperveins', 4, 'story:grumbold_dead', 'It came to blows at his claim. Grumbold Coppervein is dead.'),
('copperveins', 5, 'story:thalgrim_freed', 'At Gol\'Bolar Quarry, Rockjaw troggs had a dwarf in chains, tipping ore into a crack in the cliff - filling something in. He went free. His name is Thalgrim Coppervein.'),
('copperveins', 6, 'story:copperveins_hunt', 'Thalgrim is Grumbold\'s brother. Two Copperveins are looking for the man who sold that claim, and they aren\'t being quiet about it.'),
('copperveins', 7, 'story:thalgrim_mourns', 'We told Thalgrim his brother was dead. He took it the way dwarves do: quietly, and for a long time.'),
('crown', 0, 'resolved:150', 'In Ironforge, Moira Thaurissan - Magni\'s daughter, a Dark Iron by marriage and by blood - holds the High Seat as regent, while her father stands turned to diamond behind the throne.'),
('crown', 1, 'story:magni_hope', 'We laid a shard of the king\'s diamond before her. Magni is alive in there, and Moira means to find the way to bring him back.'),
('crown', 2, 'story:moira_council', 'She agreed to call the clans - Bronzebeard, Wildhammer and her own Dark Irons - to rule together, as a council.'),
('crown', 3, 'resolved:158', 'In the Military Ward, a cell of Bronzebeard loyalists was planning to kill the regent.'),
('crown', 4, 'story:loyalists_stand_down', 'They stood down, to wait for the clans.'),
('crown', 5, 'story:loyalists_signet', 'We gave them the king\'s own signet, and they knelt to it.'),
('crown', 6, 'story:moira_murdered', 'We left them to their plan, and they carried it out. Moira Thaurissan was killed at her evening audience; the loyalists hold the High Seat.'),
('crown', 7, 'story:loyalists_dead', 'It came to a fight in the Military Ward. The loyalist cell is no more.'),
('crown', 8, 'story:moira_dead', 'We killed the regent on her own throne. Ironforge\'s High Seat stands empty.'),
('crown', 9, 'story:moira_council,story:loyalists_stand_down,!story:regent_gone', 'The clans came. Muradin Bronzebeard and Falstad Wildhammer sit beside Moira now: the Council of Three Hammers rules Ironforge.'),
('crown', 10, 'story:forger_exposed', 'In the Vault, a Dark Iron senator was forging deeds to the Bronzebeard holdings. The bankers have the true ones now.'),
('crown', 11, 'story:copperveins_avenged', 'He was also the man selling false claims in Kharanos. The Copperveins came for their reckoning.'),
('crown', 12, 'story:forger_shamed', 'A Dark Iron senator forging deeds in the Vault put down his pen - for now.'),
('crown', 13, 'story:envoy_recalled', 'In Stormwind, the regent\'s envoy to Lady Prestor turned for home without a treaty.'),
('crown', 14, 'story:refugees_home', 'The mountaineers who fled the regency to Stormwind have gone home.'),
('crown', 15, 'story:magni_ritual_known', 'The cult\'s own ritual says how the king was bound - and so, how he might be unbound.'),
('crown', 16, 'story:magni_restored', 'The priests of the vigil worked the ritual backwards for three days and nights. King Magni Bronzebeard is flesh again, and stands behind the High Seat.'),
('crown', 17, 'story:magni_restored,story:moira_council', 'He did not take the throne back. He took the fourth chair at his daughter\'s council, and said it was the best seat in the house.'),
('lady', 0, 'resolved:177', 'In an Old Town alley an SI:7 man named Renzik told us what the spymasters can\'t prove: the Lady Prestor on Stormwind\'s throne is not a lady.'),
('lady', 1, 'story:si7_letter', 'We carried his sealed letter to Archbishop Benedictus.'),
('lady', 2, 'story:si7_trusted', 'SI:7 counts us among its own now.'),
('lady', 3, 'resolved:172', 'Behind the Keep, Lord Gregor Lescovar was selling the Keep\'s secrets to the Defias Brotherhood.'),
('lady', 4, 'story:lescovar_names', 'He gave up the names of his Brotherhood friends.'),
('lady', 5, 'story:keep_secrets', 'We walked out of his garden carrying the Keep\'s watch rotas, meant for VanCleef.'),
('lady', 6, 'resolved:170', 'We stood before the Lady Prestor on the king\'s throne.'),
('lady', 7, 'story:lady_seen', 'When she saw the black scale her eyes went gold and slit, for a heartbeat. Whatever she is, she is no woman.'),
('lady', 8, 'story:lady_fled', 'She left the throne by the king\'s private stair and has not been seen since. Wherever she went, she went alive.'),
('lady', 9, 'story:lady_unmasked', 'With the Archbishop\'s priests at the door, her shadow betrayed her in front of the whole court. The Lady Prestor was a black dragon, and all Stormwind knows it now.'),
('lady', 10, 'story:lady_slain', 'It came to a fight in the throne room. What died there was not a woman.'),
('lady', 11, 'story:lady_gone', 'Highlord Bolvar Fordragon sits on the throne of Stormwind again.'),
('lady', 12, 'resolved:118', 'In Lethlor Ravine, a black drake was missing one egg from her clutch of seven.'),
('lady', 13, 'story:drake_egg_returned', 'We gave the egg back. She curled round all seven, and let us go.'),
('lady', 14, 'story:drake_sent_on_ogres', 'We told her the ogres had taken it. The Dustbelchers will be counting their dead.'),
('lady', 15, 'story:drake_slain', 'We killed her in the ravine.'),
('lady', 16, 'story:morgaine_retired', 'Morgaine the Sly of the Defias read her own name on VanCleef\'s list of the \'retired\', and retired.'),
('drums', 0, 'resolved:248', 'In Orgrimmar\'s Valley of Honor, Garrosh Hellscream - Grom\'s son - paces like a caged wolf, hungry for a war with the Alliance.'),
('drums', 1, 'story:garrosh_hunts_blade', 'We told him the Burning Blade was in his city. He went hunting demon-worshippers instead of us.'),
('drums', 2, 'story:garrosh_father', 'We gave him his father\'s pendant. For a moment, he looked very young.'),
('drums', 3, 'resolved:246', 'Eitrigg, the Warchief\'s old friend, commands his guard - and wears a token of the Silver Hand.'),
('drums', 4, 'story:eitrigg_peace', 'He remembered Tirion Fordring, who gave up everything for him. He will speak against the war.'),
('drums', 5, 'resolved:234', 'In Thunder Bluff, Baine Bloodhoof keeps the great war drum on the rise, at his father\'s word and Magatha\'s whispering.'),
('drums', 6, 'story:drums_silenced', 'The drums are silent. Baine laid the sticks down.'),
('drums', 7, 'resolved:232', 'Magatha Grimtotem, the Elder Crone, sits in her smoky lodge behind all the talk of war.'),
('drums', 8, 'story:magatha_exposed', 'Her ledger told the rest: every Grimtotem warband from Stonetalon to Feralas, waiting for the night Cairne falls.'),
('drums', 9, 'story:magatha_fled', 'We named the vial in her sleeve. She ran.'),
('drums', 10, 'resolved:218', 'In the Undercity\'s Apothecarium, Master Apothecary Faranell brews a new plague in copper vats.'),
('drums', 11, 'story:plague_stopped', 'The plague will not be leaving the Apothecarium. Not this year.'),
('drums', 12, 'story:plague_doubt', 'We showed him the queen\'s own orders: Stormwind first, then any Forsaken who argued. He is thinking about that.'),
('drums', 13, 'resolved:212', 'Varimathras, the queen\'s enslaved dreadlord, offered us a bargain against her.'),
('drums', 14, 'story:dreadlord_deal', 'We took it. Her doors will be unwatched on the night we come for her.'),
('drums', 15, 'story:dreadlord_leashed', 'We hold a letter that would see him unmade if she read it. He\'ll keep out of our way.'),
('drums', 16, 'resolved:208', 'In the Rogues\' Quarter, the Deathstalkers\' executor kept his agents very still, with their sleeves pulled down.'),
('drums', 17, 'story:deathstalkers_know', 'The Apothecaries had been testing their plague on the queen\'s own Deathstalkers. The executor knows it now.'),
('drums', 18, 'story:zygand_at_vats', 'Executor Zygand went down to the Apothecarium to discuss it. The vats were emptied that night.'),
('drums', 19, 'resolved:243', 'In the Valley of Spirits, Vol\'jin of the Darkspear watched us climb with cool, amused eyes.'),
('drums', 20, 'story:voljin_stays', 'He has no love for Hellscream\'s war. The Darkspear will stay in their valley.'),
('drums', 21, 'resolved:238', 'Overlord Runthak minds a gate in the Valley of Strength, and wants to matter again.'),
('drums', 22, 'story:runthak_to_garrosh', 'We sent him to have it out with Hellscream.'),
('drums', 23, 'resolved:153', 'In a side-tunnel off the Deeprun Tram, a Forsaken and an orc were drawing maps of Ironforge\'s guard posts.'),
('drums', 24, 'story:spies_cipher', 'We read their own cipher back to them. They burned everything and went home.'),
('drums', 25, 'story:spies_gone', 'Their maps never reached Orgrimmar.'),
('drums', 26, 'story:drums_silenced,story:eitrigg_peace,story:plague_stopped', 'The drums are silent in Thunder Bluff, the plague is spilled in the Undercity, and Eitrigg speaks for peace in Orgrimmar. Whatever the Warchief decides, the Horde will not be marching on the Alliance this season.'),
('doors', 0, 'resolved:156', 'In the Hall of Explorers, an earthen guardian from Uldaman - a museum piece for three hundred years - stepped off its plinth the day the king was turned to stone.'),
('doors', 1, 'story:watcher_rests', 'It went back to its plinth.'),
('doors', 2, 'story:watcher_broken', 'It came to blows in the Hall. The guardian is rubble.'),
('doors', 3, 'resolved:114', 'At Hammertoe\'s Dig in the Badlands, a Dark Iron scholar, Magregan Deepshadow, had taken the League\'s shaft, digging for a titan door.'),
('doors', 4, 'story:dig_warded', 'We showed him the keepers\' mark on his own lintel. He stopped digging.'),
('doors', 5, 'story:magregan_sent', 'We gave him Hammertoe\'s map. He went off after the real vault, under the Uldaman road.'),
('doors', 6, 'story:dig_abandoned', 'He believed Hammertoe was coming with forty rifles, and left.'),
('doors', 7, 'story:magregan_dead', 'It came to a fight at the dig. Magregan Deepshadow is dead.'),
('doors', 8, 'resolved:124', 'Further on, a ridge of red rock opened its eyes: a giant, asleep since the land was green, woken by shafts dug into its back.'),
('doors', 9, 'story:anathemus_sleeps', 'It went back to sleep.'),
('doors', 10, 'story:anathemus_dead', 'We fought a mountain, and won.'),
('doors', 11, 'resolved:82', 'In the Arathi hills, Drywhisker kobolds had fled their own tunnel, terrified of a voice deep in an old dwarven hall.'),
('doors', 12, 'story:drywhisker_left', 'The kobolds left for good. The old hall is quiet again.'),
('doors', 13, 'resolved:136', 'In the Searing Gorge, Dark Iron geologists were tapping at a seam, looking for thorium.'),
('doors', 14, 'story:geologists_gone', 'They moved their camp, and the seam they were tapping was left alone.'),
('doors', 15, 'resolved:138', 'At the end of a ruined League dig in the Gorge, Obsidion - a golem of black glass - still guards an expedition that came back and never left again.'),
('doors', 16, 'story:obsidion_rests', 'We told it the watch was over. It knelt down among their bones.'),
('doors', 17, 'story:obsidion_relieved', 'The expedition\'s own rune relieved it. It walked away up the Gorge.'),
('doors', 18, 'story:obsidion_broken', 'We broke it.'),
('doors', 19, 'story:watcher_heard_keeper', 'We told the guardian in the Hall about the black-glass keeper. It understood.'),
('doors', 20, 'story:dig_ended,story:anathemus_sleeps,story:keeper_stood_down,story:watcher_rests', 'Every door the digging woke has been shut again. The League has written our names in its book of the deep.'),
('twilight', 0, 'resolved:154', 'In Ironforge\'s Forlorn Cavern, a preacher told the hungry that the king\'s turning to stone was a sign from the deep.'),
('twilight', 1, 'story:cult_doubted', 'We named it a ritual, in front of his crowd. They stopped filling his bowl.'),
('twilight', 2, 'story:preacher_mocked', 'We laughed him off his crate.'),
('twilight', 3, 'story:magni_ritual_known', 'We read out the cult\'s own ritual: the king was turned to stone by their hands, at the Great Forge, at an hour they chose. The crowd chased them out of the cavern.'),
('twilight', 4, 'story:preacher_dead', 'It came to blows in the cavern. The preacher is dead.'),
('twilight', 5, 'resolved:140', 'Under Firewatch Ridge, a farm boy in a Twilight robe much too big for him was praying to a lumpy clay idol.'),
('twilight', 6, 'story:idolater_home', 'He went home to Redridge.'),
('twilight', 7, 'resolved:134', 'On Firewatch Ridge, a Twilight highlord with burning eyes preached the end of the world to two followers.'),
('twilight', 8, 'story:highlord_disgraced', 'His own followers turned on him, and he ran.'),
('twilight', 9, 'story:highlord_dead', 'We ended his sermon for good.'),
('twilight', 10, 'resolved:176', 'In the Slaughtered Lamb\'s cellar in Stormwind, two warlocks were chalking a circle for something far too big, for a client who paid well.'),
('twilight', 11, 'story:circle_broken', 'The circle was never finished.'),
('twilight', 12, 'story:lamb_client', 'At the door, the elder told us one thing about the client: they wore black and gold.'),
('twilight', 13, 'story:magni_ritual_known,story:highlord_gone,story:circle_broken', 'The cult\'s preacher is run out of Ironforge, its highlord is gone from the Gorge and its circle in Stormwind is scrubbed away. The Twilight\'s Hammer is not finished - it never is - but it has nowhere left to stand in these mountains.'),
('exiles', 0, 'resolved:8', 'In Coldridge Valley, a gnome tinker named Fizzik had lost his frost-coil schematics, and was sure we\'d taken them.'),
('exiles', 1, 'story:fizzik_flaw', 'The schematics had a fatal flaw. Fizzik decided the thief was welcome to them.'),
('exiles', 2, 'story:nim_forgiven', 'His apprentice Nim had copied them, out of nothing worse than wanting to learn. Fizzik put him on frost-coils.'),
('exiles', 3, 'story:nim_punished', 'His apprentice Nim had taken them. Fizzik took Nim\'s tools.'),
('exiles', 4, 'resolved:14', 'In the hills of Dun Morogh, three gnomes sick from Gnomeregan\'s poison were living wild, half mad with it.'),
('exiles', 5, 'story:fimble_left', 'Their leader remembered his own name - Fimble - and led them away, toward cleaner air.'),
('exiles', 6, 'story:fimble_to_fizzik', 'We sent them to Fizzik\'s camp in Coldridge. He needed hands that knew a spanner.'),
('exiles', 7, 'resolved:155', 'In Ironforge, Tinker Town\'s refugees were picking through scrap, forgotten by everyone, Mekkatorque included.'),
('exiles', 8, 'story:fimble_in_tinkertown', 'Fimble\'s folk made it there. He vouched for us.'),
('exiles', 9, 'story:refugees_promised', 'We promised to speak to Mekkatorque for them.'),
('exiles', 10, 'story:refugees_healed', 'We gave them a jar of real Gnomeregan salve.'),
('exiles', 11, 'story:refugees_hired', 'We sent them to Lotwil Veriatus in the Badlands, who has his golem back and more work than hands.'),
('exiles', 12, 'resolved:120', 'In the Badlands, a gnomish siege golem had wandered off from its maker and was guarding a patch of dust.'),
('exiles', 13, 'story:golem_home', 'It went home to Lotwil\'s camp.'),
('exiles', 14, 'story:golem_scrapped', 'We took it apart the hard way.'),
('exiles', 15, 'story:fimble_left,story:refugees_helped', 'Fimble\'s folk found their way to Tinker Town, and Tinker Town found its way back to work.'),
('advance', 0, 'resolved:151', 'In Ironforge\'s Great Forge, an Anvilrage overseer drove the city\'s smiths to make a thousand blades for the regent - and the smiths were slowing down on purpose.'),
('advance', 1, 'story:forge_fair', 'He gave them fair wages and put the whip away.'),
('advance', 2, 'story:forge_guild_rises', 'We raised the forgemasters\' old guild hammer, and forty smiths turned to face him. He left.'),
('advance', 3, 'resolved:161', 'In the Stonefire Tavern, three Dark Iron drunks had the place to themselves.'),
('advance', 4, 'story:stonefire_sang', 'We sang them the Grim Guzzler\'s song from home. They paid their tab and left in tears.'),
('advance', 5, 'story:stonefire_paid', 'They paid their tab and left, grumbling.'),
('advance', 6, 'story:stonefire_brawl', 'The Stonefire got its brawl.'),
('advance', 7, 'resolved:34', 'At the Stonewrought Dam, two Dark Irons were packing powder charges stamped with the anvil of Thaurissan.'),
('advance', 8, 'story:dam_saved', 'The charges were never set. The dam stands, and Loch Modan stays where it is.'),
('advance', 9, 'resolved:67', 'In the Wetlands, Balgaras the Foul was brewing fire-oil by the cauldronful, for a buyer.'),
('advance', 10, 'story:oil_spoiled', 'There will be no oil from that cauldron.'),
('advance', 11, 'story:oil_to_forge', 'They carried it back to their forge to brew it properly. We let them.'),
('advance', 12, 'resolved:122', 'In the Badlands, Angor Fortress held its walls for an emperor who had forgotten it.'),
('advance', 13, 'story:angor_to_gorge', 'The garrison marched for the Searing Gorge.'),
('advance', 14, 'story:angor_fallen', 'Angor fell to us.'),
('advance', 15, 'resolved:144', 'In the Searing Gorge, the Dark Irons kept a creature of living flame chained between four stakes, and bled it into their furnaces.'),
('advance', 16, 'story:forges_cold', 'We freed it. The Gorge\'s forges have lost their fire.'),
('advance', 17, 'story:smoldar_sworn', 'It swore an oath in the tongue of flame to leave this world alone.'),
('advance', 18, 'resolved:142', 'A steamsmith was building a war golem, the Mark Nine, at his forge in the Gorge.'),
('advance', 19, 'story:golem_to_emperor', 'We sent him to show it to the Emperor himself.'),
('advance', 20, 'story:golem_stalled', 'The Mark Nine will not be marching anywhere.'),
('advance', 21, 'resolved:132', 'On the Cauldron\'s rim, Slave Master Blackheart drove a chain-gang of slaves for a quota he was missing.'),
('advance', 22, 'story:slaves_freed', 'The chains came off. The slaves ran for Thorium Point.'),
('advance', 23, 'story:dam_saved,story:oil_spoiled,story:forges_cold,story:slaves_freed', 'Thaurissan\'s road to Ironforge has no flood to clear it, no oil to burn its gates, no fire in its forges and no slaves to work them. Whatever the Emperor planned for this year, it will wait.'),
('frostmane', 0, 'resolved:6', 'In Coldridge Valley a Frostmane novice was keeping a ritual circle for Grik\'nir the Cold.'),
('frostmane', 1, 'story:grik_hurried', 'We told him Grik\'nir was tired of waiting. He ran.'),
('frostmane', 2, 'resolved:9', 'Grik\'nir the Cold held a camp of frozen bones in Coldridge, and burned his own whelps for sport.'),
('frostmane', 3, 'found:whelptoken', 'Among his offerings we found a little carved wolf - a whelp\'s toy.'),
('frostmane', 4, 'story:whelps_fled', 'His whelps threw down their spears and ran.'),
('frostmane', 5, 'story:grik_hunts_vejrek', 'We told him the tribe had a new chief. He went howling off to find out who.'),
('frostmane', 6, 'story:grik_dead', 'Grik\'nir the Cold is dead.'),
('frostmane', 7, 'resolved:11', 'On Shimmer Ridge, three Frostmane seers chewed shimmerweed and listened to the loa.'),
('frostmane', 8, 'story:seers_vision', 'We breathed the smoke with them and saw a troll in a crown of frozen bone, asleep on a throne of ram skulls, and the ice cracking under his feet.'),
('frostmane', 9, 'story:seers_turn', 'The weed rotting their minds came from their own chief, more every moon. The seers know it now.'),
('frostmane', 10, 'resolved:16', 'In the high camp, Vejrek - crowned in frozen bone, on a throne of ram skulls - means to rule the whole Frostmane tribe.'),
('frostmane', 11, 'found:frostmane_map', 'We found a hide map of his caves, with his bed marked.'),
('frostmane', 12, 'found:neat_wound', 'A hunter by the wendigo den was killed with a needle, not claws.'),
('frostmane', 13, 'story:vejrek_rises', 'We told him Grik\'nir was weak. He liked that very much.'),
('frostmane', 14, 'story:vejrek_shamed', 'His own seers\' weed undid him. His skinners walked out, and so did he.'),
('frostmane', 15, 'story:vejrek_dead', 'Vejrek is dead.'),
('frostmane', 16, 'resolved:23', 'On the road, Vejrek\'s outriders took a toll from everyone who passed.'),
('frostmane', 17, 'story:salt_toll', 'We paid them the old toll, in salt. They hadn\'t been paid properly in years.'),
('frostmane', 18, 'story:seers_turn,story:vejrek_gone', 'The seers on Shimmer Ridge dream with clear eyes now, and the Frostmane\'s war-chief is gone. Whatever the tribe becomes, it will decide for itself.'),
('masons', 0, 'resolved:173', 'Outside the city architect\'s office, the last of the stonemasons who rebuilt Stormwind after the orcs burned it were still asking for their wages. The rest of their guild has gone over to Edwin VanCleef and the Defias Brotherhood.'),
('masons', 1, 'found:wage_ledger', 'We found the guild\'s wage-ledger, with the treasury\'s seal on every page.'),
('masons', 2, 'story:masons_proof', 'In its margin: payment refused, by order from on high.'),
('masons', 3, 'story:masons_paid', 'The masons have their wages, every one of the two hundred and six.'),
('masons', 4, 'story:masons_respect', 'We set a stone straighter than any of them. They laughed, and went home for the night.'),
('masons', 5, 'story:masons_beaten', 'We broke up the picket with our fists.'),
('masons', 6, 'resolved:204', 'In the vineyard below Northshire Abbey, Garrick Padfoot of the Brotherhood was harvesting grapes that weren\'t his.'),
('masons', 7, 'found:vineyard_deed', 'We found the vineyard\'s true deed, made over to the old vintner\'s daughter.'),
('masons', 8, 'story:vineyard_returned', 'Garrick read it and left. The vineyard is hers again.'),
('masons', 9, 'story:garrick_fled', 'Garrick and his lads left in a hurry.'),
('masons', 10, 'resolved:199', 'South of the river, two runaway apprentices from the Tower of Azora worked a circle for the Brotherhood.'),
('masons', 11, 'story:wizards_home', 'They went home to Azora.'),
('masons', 12, 'resolved:191', 'At Fargodeep Mine, Narg the Taskmaster drove his kobolds to dig - too deep. Something very big turned over in its sleep below.'),
('masons', 13, 'story:narg_deal', 'Narg shook on it: he keeps his kobolds in the mine and off the farms.'),
('masons', 14, 'story:narg_friend', 'We gave Narg a real Goldshire candle. He wore it like a crown.'),
('masons', 15, 'story:masons_paid,story:vineyard_returned,story:wizards_home', 'The masons have their wages, the vintner\'s daughter her vineyard, Azora its runaways. VanCleef\'s Brotherhood was built on the city\'s broken promises. There are fewer of those now.'),
('dragonmaw', 0, 'resolved:58', 'Where the tunnel road comes out above the Wetlands, Ma\'ruk Wyrmscale of the Dragonmaw had shut it for Chieftain Nek\'rosh.'),
('dragonmaw', 1, 'story:maruk_gone', 'The road is open again.'),
('dragonmaw', 2, 'story:maruk_dead', 'Ma\'ruk is dead on his own road.'),
('dragonmaw', 3, 'resolved:64', 'In the Dragonmaw high camp, Chieftain Nek\'rosh planned his raids at a table made of a door, with a necklace of dwarven teeth round his neck.'),
('dragonmaw', 4, 'story:dragonmaw_split', 'His centurion wanted his seat. We said so out loud. When the fighting stopped, the Dragonmaw left the camp without a banner.'),
('dragonmaw', 5, 'story:dragonmaw_retreat', 'We told them Menethil was marching. They believed it, and went.'),
('dragonmaw', 6, 'story:nekrosh_dead', 'Nek\'rosh is dead.'),
('dragonmaw', 7, 'story:runthak_heard', 'In Orgrimmar, an old overlord who fought beside the Dragonmaw in the Second War heard how they ended. He didn\'t mourn them.'),
('dragonmaw', 8, 'story:maruk_gone,story:dragonmaw_broken', 'The Dragonmaw are gone from the Wetlands. Menethil\'s roads are its own again.'),
('cloaks', 0, 'resolved:81', 'High in the ruins of Stromgarde Keep, a Syndicate magus was peeling the Trollbane blood-ward off a vault door.'),
('cloaks', 1, 'found:trollbane_signet', 'We found the Trollbane family\'s signet ring.'),
('cloaks', 2, 'story:vault_sealed', 'The ward closed again, whole. Whatever the Trollbanes left in there stays theirs.'),
('cloaks', 3, 'story:magus_quit', 'She dropped her grey cloak on the vault steps and walked away. The Syndicate pays nothing and calls it a share.'),
('cloaks', 4, 'resolved:79', 'At Northfold, three Syndicate highwaymen were robbing a farmer\'s cart.'),
('cloaks', 5, 'found:wanted_poster', 'We found a wanted poster with their leader\'s face on it.'),
('cloaks', 6, 'story:highwaymen_split', 'His own men turned on him for the money.'),
('cloaks', 7, 'story:highwaymen_quit', 'They heard their magus had walked out, and gave up the road.'),
('cloaks', 8, 'story:vault_sealed,story:highwaymen_gone', 'The Syndicate has lost its magus and its road. Arathi is a little quieter.');
