INSERT INTO `dnd_story_rumor` (`id`, `zone`, `cond`, `text`) VALUES
(1, 2, 'story:copperveins_hunt', '"The Coppervein brothers came through asking after a smooth fellow who sells claims. Nobody liked the look on their faces."'),
(2, 2, 'story:thalgrim_freed,!story:copperveins_hunt', '"Thalgrim Coppervein walked out of Gol\'Bolar on his own two feet, they say. Someone pulled him out of there."'),
(3, 1, 'story:grumbold_dead', '"Old Grumbold\'s claim has gone quiet. Picked a fight with the wrong stranger, folk say."'),
(4, 4, 'story:moira_council,story:loyalists_stand_down,!story:regent_gone', '"Three seats at the High Seat now - Bronzebeard, Wildhammer and Thaurissan, scowling at each other. Better than knives, I say."'),
(5, 4, 'story:moira_murdered', '"They say the regent was killed at her own audience. Loyalists hold the throne room, and every Dark Iron in the city is packing."'),
(6, 4, 'story:moira_dead', '"The High Seat\'s empty. Someone walked in and cut the regent down. Nobody knows who rules now."'),
(7, 4, 'story:magni_hope', '"The priests keep a vigil by the king\'s statue day and night. Word is he\'s still alive in there."'),
(8, 4, 'story:forger_exposed', '"A Dark Iron senator, caught forging deeds in the Vault! The bankers are still counting."'),
(9, 12, 'story:envoy_recalled', '"The Dark Iron envoy left without his treaty. The Lady was not pleased, they say."'),
(10, 2, 'story:copperveins_avenged', '"The Copperveins are standing rounds at Thunderbrew\'s. Caught their swindler in the Vault of Ironforge, of all places."'),
(11, 12, 'story:lady_unmasked', '"A dragon! On the king\'s throne, all this time! The Cathedral bells rang for an hour."'),
(12, 12, 'story:lady_fled', '"The Lady\'s gone - walked out of the Keep one evening and never came back. Bolvar\'s on the throne again, Light be thanked."'),
(13, 12, 'story:lady_slain', '"Something huge and black died in the throne room, they say. The masons are still scrubbing the floor."'),
(14, 12, 'story:keep_secrets,!story:lady_gone', '"The Blackwings doubled the watch at the Keep. Someone\'s been selling the rotas."'),
(15, 13, 'story:morgaine_retired', '"Morgaine the Sly\'s gone from the Goldshire road. Good riddance, I say."'),
(16, 6, 'story:drake_sent_on_ogres', '"The Dustbelchers are howling. A black drake came down on their camp in the night."'),
(17, 20, 'story:garrosh_hunts_blade', '"Hellscream tore through the Cleft of Shadow last night. Not a Burning Blade jar left standing."'),
(18, 19, 'story:drums_silenced', '"The great drum on the rise is quiet. Baine laid the sticks down himself."'),
(19, 19, 'story:magatha_exposed', '"The Grimtotem are leaving the Elder Rise in the night. Something about a ledger."'),
(20, 17, 'story:plague_stopped', '"The Apothecarium\'s vats are cold. Faranell won\'t say why."'),
(21, 4, 'story:drums_silenced,story:eitrigg_peace,story:plague_stopped', '"Word from the Barrens: the Horde\'s war-talk has gone quiet. Nobody knows why, and nobody\'s complaining."'),
(22, 12, 'story:drums_silenced,story:eitrigg_peace,story:plague_stopped', '"The Horde was gathering for war, they say - and then it stopped. The Lord Admiral can\'t make it out."'),
(23, 4, 'story:magni_restored', '"The king\'s awake! Flesh and beard and temper, all of it. They say he wept on his daughter\'s shoulder."'),
(24, 0, 'story:magni_restored', '"Magni Bronzebeard walks again, they\'re saying in every tavern from here to the Wetlands. Drink to that."'),
(25, 4, 'story:watcher_rests', '"The Uldaman guardian\'s back on its plinth in the Hall of Explorers. The scholars are pretending they were never worried."'),
(26, 6, 'story:dig_ended', '"Hammertoe\'s Dig is quiet. Whoever took it has gone, and good riddance."'),
(27, 6, 'story:anathemus_sleeps', '"The red ridge has stopped shaking. You\'d almost think it was asleep."'),
(28, 7, 'story:drywhisker_left', '"The Drywhisker kobolds packed up and left. Nobody knows what scared them, and nobody\'s going in to look."'),
(29, 10, 'story:obsidion_relieved', '"A glass golem walked straight through Thorium Point last week. Didn\'t even look at us."'),
(30, 4, 'story:magni_ritual_known', '"The Forlorn Cavern lot did it - did the king, I mean. Read out in front of everyone. The guard\'s still looking for the ones who ran."'),
(31, 10, 'story:highlord_disgraced', '"The doom-preacher on Firewatch Ridge got chased off his own pulpit by his own people. Best sermon he ever gave."'),
(32, 12, 'story:circle_broken', '"Something happened in the Lamb\'s cellar. The warlocks have gone very quiet, and they\'re drinking upstairs like the rest of us."'),
(33, 4, 'story:refugees_promised', '"Mekkatorque himself came down to the Tinker Town corner last night, they say. Someone shamed him into it."'),
(34, 4, 'story:refugees_hired', '"Half the gnomes in Tinker Town have gone off to the Badlands, to work for some inventor with a golem."'),
(35, 1, 'story:fimble_to_fizzik', '"Fizzik\'s camp has three more gnomes in it - green-tinged, but cheerful. They\'re building something."'),
(36, 2, 'story:fimble_left', '"The glowing gnomes are gone from the hills. Went looking for clean air, someone said."'),
(37, 3, 'story:dam_saved', '"Someone found Dark Iron powder by the dam! Packed and stamped. The Mountaineers have doubled the watch on the wall."'),
(38, 5, 'story:oil_spoiled', '"There was a bang in the hills last week you could hear in Menethil. Took the top off a hill, they say."'),
(39, 6, 'story:angor_to_gorge', '"Angor Fortress is empty. The whole garrison marched off north one morning."'),
(40, 10, 'story:forges_cold', '"The Dark Iron forges in the Gorge have gone cold. Something got loose."'),
(41, 10, 'story:slaves_freed', '"Six of Blackheart\'s slaves walked into Thorium Point with their chains still on their wrists. We cut them off."'),
(42, 4, 'story:forge_guild_rises', '"The Great Forge rings like it used to. The smiths took it back, with an old hammer and a lot of nerve."'),
(43, 4, 'story:dam_saved,story:oil_spoiled,story:forges_cold,story:slaves_freed', '"The Mountaineers say the Dark Iron war-camps have gone quiet, from the Loch to the Gorge. Someone\'s been busy."'),
(44, 1, 'story:grik_hunts_vejrek', '"Grik\'nir went tearing up the pass toward the high camp, howling. Haven\'t seen him since."'),
(45, 2, 'story:vejrek_gone', '"The Frostmane war-camp\'s quiet. Vejrek\'s gone - nobody knows where."'),
(46, 2, 'story:seers_turn', '"The troll seers on Shimmer Ridge have stopped chewing that black weed. One of them waved at a mountaineer."'),
(47, 2, 'story:vejrek_rises,!story:vejrek_gone', '"Vejrek\'s outriders are saying their chief will have the whole tribe by spring."'),
(48, 12, 'story:masons_paid', '"The masons got paid! Two years late, but every copper. They\'re drinking it at the Pig and Whistle."'),
(49, 13, 'story:vineyard_returned', '"The old vintner\'s girl has her vineyard back. The Abbey\'s sending monks to help with the harvest."'),
(50, 13, 'story:narg_friend', '"There\'s a kobold at Fargodeep with a big white candle on his head, and he WAVES at people."'),
(51, 5, 'story:maruk_gone', '"The tunnel road\'s open! Carts through from Loch Modan for the first time in a month."'),
(52, 5, 'story:dragonmaw_broken', '"Smoke over the Dragonmaw camp, and not a banner on the hill. Menethil\'s breathing again."'),
(53, 7, 'story:magus_quit', '"A woman in her shirtsleeves came down from Stromgarde last week and asked the way to Southshore. Didn\'t say a word about the Syndicate. Didn\'t need to."'),
(54, 7, 'story:highwaymen_gone', '"The Northfold road\'s clear. Farmers are taking their carts to market again."'),
(55, 20, 'story:voljin_stays', '"The Darkspear drums are beating for the loa, not for war. Vol\'jin\'s keeping his people home."'),
(56, 20, 'story:runthak_to_garrosh', '"Old Runthak stormed into the Valley of Honor and shouted at Hellscream for an hour. Best show in Orgrimmar."'),
(57, 17, 'story:deathstalkers_know', '"The Deathstalkers went down to the Apothecarium in force last night. Nobody\'s saying what for."');
INSERT INTO `dnd_story_milestone` (`id`, `cond`, `title`, `headline`, `sender`, `subject`, `letter`, `money`, `item`, `sort`) VALUES
('crown_council', 'story:moira_council,story:loyalists_stand_down,!story:regent_gone', 'The Council of Three Hammers', 'The clans have come to Ironforge: Bronzebeard, Wildhammer and Dark Iron rule together.', 9100101, 'The Council of Three Hammers', 'Friend - the High Seat has three chairs now, and Ironforge has you to thank for the third. The clans remember who talked them to the table instead of the gallows. Take this with the Council\'s gratitude. - Muradin Bronzebeard', 50000, 858, 1),
('crown_regent_slain', 'story:moira_dead', 'The High Seat Stands Empty', 'The regent of Ironforge is dead on her own throne.', 9100103, 'The High Seat', 'The regent is dead, and the city is mine to hold until the clans decide who sits in that chair. I didn\'t ask how it was done. I\'m paying you for the doing of it. - Captain Durgen Stoutbeard', 30000, 858, 2),
('crown_regent_murdered', 'story:moira_murdered', 'The Regent Is Murdered', 'Moira Thaurissan has been murdered in Ironforge.', 9100103, 'The High Seat', 'The loyalists did what they swore they would. The city is mine to hold now. You stood aside and let it happen; some would call that wisdom. Here is what wisdom pays. - Captain Durgen Stoutbeard', 30000, 858, 3),
('magni_restored', 'story:magni_restored', 'The King Wakes', 'King Magni Bronzebeard walks again in Ironforge.', 2784, 'Diamond and Flesh', 'I\'m told I owe my heartbeat to you. A king doesn\'t forget that kind of debt, and this one won\'t. Come and see me in the throne room some day - I\'ll pour. - Magni', 100000, 858, 4),
('lady_gone', 'story:lady_gone', 'Stormwind\'s Throne Restored', 'Highlord Bolvar Fordragon sits on the throne of Stormwind again.', 1748, 'The King\'s Hall', 'Whatever sat on that throne is gone, and the kingdom breathes easier for it. Stormwind\'s thanks, and mine. SI:7 will be watching the stair she left by. - Bolvar Fordragon', 50000, 858, 5),
('drums_silenced', 'story:drums_silenced,story:eitrigg_peace,story:plague_stopped', 'The Drums Fall Silent', 'The Horde\'s march to war has stalled: the drums are quiet, and the plague stays in its vats.', 4949, 'From Orgrimmar', 'I don\'t know who you are, or why you did it. But my people will see another winter without war because of you. Lok\'tar. - Thrall', 80000, 858, 6),
('doors_shut', 'story:dig_ended,story:anathemus_sleeps,story:keeper_stood_down,story:watcher_rests', 'The Deep Doors Are Shut', 'Every door the digging woke has been shut again.', 5387, 'For the League\'s Records', 'The League has written it all down, and closed the file, and I have locked the file in my desk. Some things are better asleep. With the League\'s thanks - and its discretion. - Magellas', 80000, 858, 7),
('twilight_routed', 'story:magni_ritual_known,story:highlord_gone,story:circle_broken', 'The Cult Is Routed', 'The Twilight\'s Hammer has lost its preacher, its highlord and its circle.', 1284, 'A Blessing', 'The Light does not often get help this direct. The cult will try again - they always do - but not soon, and not here. Go with my blessing. - Benedictus', 80000, 858, 8),
('exiles_home', 'story:fimble_left,story:refugees_helped', 'Tinker Town Remembers', 'Gnomeregan\'s exiles have found their way home to Tinker Town.', 7937, 'Gnomish Gratitude (with Diagram)', 'On behalf of every gnome who ever slept in a scrap heap: thank you. Enclosed: reward, and a diagram of a better reward I am still building. - Gelbin Mekkatorque', 60000, 858, 9),
('advance_stalled', 'story:dam_saved,story:oil_spoiled,story:forges_cold,story:slaves_freed', 'Thaurissan\'s Road Is Broken', 'The Dark Iron advance on Ironforge has nothing left to march on.', 9100101, 'The Emperor\'s Road', 'No flood, no oil, no forges, no slaves. The Emperor can sit in his mountain and stew. Ironforge sleeps sound tonight, and you\'re the reason. - Muradin', 80000, 858, 10),
('frostmane_calm', 'story:seers_turn,story:vejrek_gone', 'The Frostmane Are Quiet', 'The Frostmane seers dream with clear eyes, and the war-chief is gone.', 1252, 'From Kharanos', 'Thirty winters I\'ve watched those peaks for trouble. This is the first one I\'ll sleep through. A round on me, and something for the road. - Senir Whitebeard', 40000, 858, 11),
('masons_due', 'story:masons_paid,story:vineyard_returned,story:wizards_home', 'Old Debts Paid', 'The stonemasons have their wages, and Elwynn its peace.', 1646, 'Accounts Settled', 'The Guild\'s ledger balances for the first time in fifteen years. I am told this is your doing. The city architect\'s office is - grateful. - Baros Alexston', 60000, 858, 12),
('dragonmaw_gone', 'story:maruk_gone,story:dragonmaw_broken', 'The Wetlands Are Free', 'The Dragonmaw are gone from the Wetlands.', 2104, 'From Menethil Harbor', 'The roads are ours again and the caravans are moving. Menethil drinks to you. - Captain Stoutfist', 60000, 858, 13),
('cloaks_broken', 'story:vault_sealed,story:highwaymen_gone', 'The Syndicate Breaks', 'The Syndicate has lost its magus and its road in Arathi.', 2700, 'From Refuge Pointe', 'Arathi\'s a little quieter, and the League of Arathor owes you for it. - Captain Nials', 60000, 858, 14);
